<?php
/**
 * `GET /bcm/v1/categories` (SPEC §7, §4.7, §12.2): the whole `product_cat`
 * hierarchy as one nested array, each node with its own product count and
 * its count including descendants under the grid's active conditions. It
 * takes the grid's mode, search and filter arguments exactly as
 * `/products` does, generated by RouteSchema; a category filter is accepted
 * and left out of the counts (Categories\CategoryTree).
 *
 * @package BulkCatalogueManager
 * @license GPL-3.0-or-later
 */

declare( strict_types = 1 );

namespace BulkCatalogueManager\Rest;

use BulkCatalogueManager\Categories\Cache;
use BulkCatalogueManager\Categories\CategoryTree;
use BulkCatalogueManager\Fields\Registry;

defined( 'ABSPATH' ) || exit;

/**
 * The categories route.
 */
final class CategoriesController implements ReadController {
	/**
	 * The route, under Access::REST_NAMESPACE.
	 */
	public const ROUTE = '/categories';

	/**
	 * The grid arguments besides the per-field filters that decide which products count.
	 */
	public const CONDITION_ARGS = [ 'search', 'mode' ];

	/**
	 * Route arguments and schemas.
	 *
	 * @var RouteSchema
	 */
	private RouteSchema $schema;

	/**
	 * The tree service.
	 *
	 * @var CategoryTree
	 */
	private CategoryTree $tree;

	/**
	 * Build over a registry.
	 *
	 * @param Registry          $registry Field registry.
	 * @param CategoryTree|null $tree     Tree service; the plugin's by default.
	 */
	public function __construct( Registry $registry, ?CategoryTree $tree = null ) {
		$this->schema = new RouteSchema( $registry );
		$this->tree   = $tree ?? new CategoryTree();
	}

	/**
	 * Add the route through the registrar, and the tree cache's invalidation hooks.
	 *
	 * @param Routes $routes The registrar.
	 */
	public function register_routes( Routes $routes ): void {
		Cache::register_hooks();
		$routes->add(
			self::ROUTE,
			[
				[
					'methods'             => 'GET',
					'callback'            => [ $this, 'get_items' ],
					'permission_callback' => [ Access::class, 'can_read' ],
					'args'                => $this->args(),
				],
				'schema' => [ $this, 'get_item_schema' ],
			]
		);
	}

	/**
	 * The route's arguments: the grid's search and mode, and one argument per filterable field.
	 *
	 * @return array<string, array<string, mixed>>
	 */
	public function args(): array {
		return array_intersect_key( $this->schema->query_args(), array_flip( self::CONDITION_ARGS ) ) + $this->schema->filter_args();
	}

	/**
	 * The nested tree.
	 *
	 * @param \WP_REST_Request $request The request, its arguments validated and sanitised by core.
	 */
	public function get_items( \WP_REST_Request $request ): \WP_REST_Response|\WP_Error {
		$params = array_intersect_key( $request->get_params(), $this->args() );
		try {
			$criteria = CategoryTree::criteria( $this->schema->criteria_input( $params ) );
		} catch ( \InvalidArgumentException $e ) {
			return Refusal::invalid(
				'bcm_invalid_value',
				__( 'The category counts could not use the current filters. Clear the filters and try again.', 'bulk-catalogue-manager-for-woocommerce' ),
				[ 'details' => $e->getMessage() ]
			);
		}
		return new \WP_REST_Response( $this->tree->get( $criteria ), 200 );
	}

	/**
	 * The schema of one node; `children` holds nodes of the same shape.
	 *
	 * @return array<string, mixed>
	 */
	public function get_item_schema(): array {
		$count = [
			'type'    => 'integer',
			'minimum' => 0,
		];
		return [
			'$schema'    => RouteSchema::DIALECT,
			'title'      => 'bcm-category',
			'type'       => 'object',
			'properties' => [
				'id'                   => [
					'type'     => 'integer',
					'required' => true,
				],
				'name'                 => [ 'type' => 'string' ],
				'slug'                 => [ 'type' => 'string' ],
				'description'          => [
					'description' => __( 'The category\'s description as stored, to show as text; empty when it has none.', 'bulk-catalogue-manager-for-woocommerce' ),
					'type'        => 'string',
				],
				'parent'               => [
					'description' => __( 'Parent category id; 0 at the top level, including a category whose parent no longer exists.', 'bulk-catalogue-manager-for-woocommerce' ),
					'type'        => 'integer',
				],
				'depth'                => [
					'description' => __( 'Level in the tree, from 0 at the top.', 'bulk-catalogue-manager-for-woocommerce' ),
					'type'        => 'integer',
				],
				'order'                => [
					'description' => __( 'Position among its siblings: the order set by moving categories here, or WooCommerce\'s stored category order for a category never moved here. Moved categories come first, then the rest in this order, then by name.', 'bulk-catalogue-manager-for-woocommerce' ),
					'type'        => 'integer',
				],
				'count'                => [ 'description' => __( 'Products in this category that match the other active filters.', 'bulk-catalogue-manager-for-woocommerce' ) ] + $count,
				'countWithDescendants' => [ 'description' => __( 'Products in this category or any category below it that match the other active filters, each counted once.', 'bulk-catalogue-manager-for-woocommerce' ) ] + $count,
				'children'             => [
					'description' => __( 'Categories directly below this one, in order, each of the same shape.', 'bulk-catalogue-manager-for-woocommerce' ),
					'type'        => 'array',
					'items'       => [ 'type' => 'object' ],
				],
			],
		];
	}
}
